func TestGhostlinePrivacyFeaturesOmitted(t *testing.T) {
	if buildfeatures.HasLogTail || buildfeatures.HasNetLog || buildfeatures.HasClientUpdate {
		t.Fatal("Ghostline mesh tests require all three privacy omission build tags")
	}
	if buildfeatures.HasDebug || buildfeatures.HasServe || buildfeatures.HasWebClient || buildfeatures.HasOutboundProxy {
		t.Fatal("Ghostline mesh tests require ts_omit_debug, ts_omit_serve, ts_omit_webclient and ts_omit_outboundproxy")
	}
	// ACME certificates are only used by Serve/Funnel and the cert command, all omitted;
	// upstream feature/acme does not compile without serve.
	if buildfeatures.HasACME {
		t.Fatal("Ghostline mesh tests require ts_omit_acme")
	}
	if buildfeatures.HasSSH || buildfeatures.HasTaildrop || buildfeatures.HasRelayServer || buildfeatures.HasPosture || buildfeatures.HasWakeOnLAN {
		t.Fatal("Ghostline mesh tests require the unused-feature omission tags (ssh, taildrop, relayserver, posture, wakeonlan)")
	}
	// Without it every local user gets full LocalAPI access over the unix socket.
	if !buildfeatures.HasUnixSocketIdentity {
		t.Fatal("ts_omit_unixsocketidentity must not be set in Ghostline builds")
	}
}

