// TestGhostlineBootstrapDNSDisabled checks that no host name is sent to a DERP
// server for bootstrap DNS, even when a cached DERP map offers candidates.
func TestGhostlineBootstrapDNSDisabled(t *testing.T) {
	if n := len(getStaticDERPMap().Regions); n != 0 {
		t.Fatalf("static DERP map has %d regions; want none", n)
	}
	cachedDERPMap.Store(&tailcfg.DERPMap{Regions: map[tailcfg.DERPRegionID]*tailcfg.DERPRegion{
		900: {RegionID: 900, Nodes: []*tailcfg.DERPNode{{Name: "900a", RegionID: 900, HostName: "relay.example", IPv4: "192.0.2.10"}}},
	}})
	defer cachedDERPMap.Store(nil)

	logged := 0
	logf := func(format string, args ...any) {
		logged++
		t.Logf(format, args...)
	}
	// Canceled, so that no network I/O happens even if a candidate were tried.
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	for _, host := range []string{"{{ControlHost}}", "controlplane.tailscale.com"} {
		addrs, err := lookup(ctx, host, logf, nil, nil)
		if err != errGhostlineBootstrapDisabled || addrs != nil {
			t.Errorf("lookup(%q) = %v, %v; want nil, %v", host, addrs, err, errGhostlineBootstrapDisabled)
		}
	}
	if logged != 0 {
		t.Errorf("lookup logged %d bootstrap DNS attempts; want none", logged)
	}
	// IP literals still map to themselves without any lookup.
	addrs, err := lookup(ctx, "192.0.2.10", logf, nil, nil)
	if err != nil || len(addrs) != 1 || addrs[0] != netip.MustParseAddr("192.0.2.10") {
		t.Errorf("lookup(192.0.2.10) = %v, %v; want the address itself", addrs, err)
	}
}

